interface BisaDiantar {
    String antar();
}

class Pesanan {
    String pembeli;
    int total;

    Pesanan(String pembeli, int total) {
        this.pembeli = pembeli;
        this.total = total;
    }
}

class PesananOnline extends Pesanan implements BisaDiantar {
    String alamat;

    PesananOnline(String pembeli, int total, String alamat) {
        super(pembeli, total);
        this.alamat = alamat;
    }

    public String antar() {
        return "Antar ke " + alamat;
    }
}

