public class Main {
    public static void main(String[] args) {
        PesananOnline p = new PesananOnline("Budi");
        p.info();
        p.antar();
    }
}

interface BisaDiantar {
    void antar();
}

class Pesanan {
    String pembeli;

    Pesanan(String pembeli) {
        this.pembeli = pembeli;
    }

    void info() {
        System.out.println(pembeli + " memesan");
    }
}

class PesananOnline extends Pesanan implements BisaDiantar {
    PesananOnline(String pembeli) {
        super(pembeli);
    }

    public void antar() {
        System.out.println("Pesanan diantar");
    }
}

